import "dotenv/config";
import { Client } from "../src/Typesense";
import type { CollectionCreateSchema } from "../src/Typesense/Collections";
import { ObjectAlreadyExists } from "../src/Typesense/Errors";
import { essays } from "./essays";
import { ConversationModelCreateSchema } from "../src/Typesense/ConversationModel";

export const client = new Client({
  nodes: [
    {
      host: "localhost",
      port: 8108,
      protocol: "http",
    },
  ],
  apiKey: "xyz",
  connectionTimeoutSeconds: 180,
});

export const collection = {
  name: "pg-essays",
  fields: [
    {
      name: "title",
      type: "string",
      facet: false,
    },
    {
      name: "text",
      type: "string",
      facet: false,
    },
    {
      name: "embedding",
      type: "float[]",
      embed: {
        from: ["title", "text"],
        model_config: {
          model_name: "ts/snowflake-arctic-embed-m",
        },
      },
    },
  ],
} as const satisfies CollectionCreateSchema;

export const model = {
  id: "pg-essays-model",
  model_name: "openai/gpt-4-turbo",
  api_key: process.env.OPENAI_API_KEY ?? "",
  history_collection: "conversation_store",
  system_prompt:
    "You are an assistant for question-answering like Paul Graham. You can only make conversations based on the provided context. If a response cannot be formed strictly using the context, politely say you don't have knowledge about that topic.",
  max_bytes: 65536,
} as const satisfies ConversationModelCreateSchema;

export async function setup() {
  try {
    console.log("Creating collection");
    await client.collections().create(collection);
    console.log("Collection created");
  } catch (error) {
    if (error instanceof ObjectAlreadyExists) {
      console.log("PG essays collection already exists");
    } else {
      console.error(error);
    }
  }

  try {
    console.log("Creating conversation store collection");
    await client.collections().create({
      name: "conversation_store",
      fields: [
        {
          name: "conversation_id",
          type: "string",
        },
        {
          name: "model_id",
          type: "string",
        },
        {
          name: "timestamp",
          type: "int32",
        },
        {
          name: "role",
          type: "string",
          index: false,
        },
        {
          name: "message",
          type: "string",
          index: false,
        },
      ],
    });
    console.log("Conversation store collection created");
  } catch (error) {
    if (error instanceof ObjectAlreadyExists) {
      console.log("Conversation store collection already exists");
    } else {
      console.error(error);
    }
  }

  // if it fails, we're failing
  console.log("Importing essays");
  await client.collections(collection.name).documents().import(essays);
  console.log("Essays imported");

  try {
    console.log("Creating conversation model");
    await client.conversations().models().create(model);
    console.log("Conversation model created");
  } catch (error) {
    if (error instanceof ObjectAlreadyExists) {
      console.log("Conversation model already exists");
    } else {
      console.error(error);
    }
  }
}

export async function teardown() {
  console.log("Deleting collection");
  await client.collections(collection.name).delete();
  console.log("Collection deleted");

  console.log("Deleting conversation store collection");
  await client.collections("conversation_store").delete();
  console.log("Conversation store collection deleted");
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { client } from "./setup";
import { StreamConfig } from "../src/Typesense/Configuration";
import { Essay } from "./essays";
import { MultiSearchResultsStreamConfig } from "../src/Typesense/Types";

describe("Streaming responses with fetch mock", () => {
  const originalFetch = global.fetch;
  const mockFetch = vi.fn();

  beforeEach(() => {
    global.fetch = mockFetch;
  });

  afterEach(() => {
    global.fetch = originalFetch;
    vi.clearAllMocks();
  });

  it("should handle streaming responses for search", async () => {
    const onChunk = vi.fn();
    const onComplete = vi.fn();
    const onError = vi.fn();

    const streamConfig: StreamConfig<Essay> = {
      onChunk,
      onComplete,
      onError,
    };

    const chunks = [
      '{"conversation_id":"123","message":"First chunk"}',
      '{"conversation_id":"123","message":"Second chunk"}',
      '{"conversation_id":"123","message":"Final chunk"}',
    ];

    const metadata = {
      found: 3,
      hits: [
        { document: { title: "Test 1" } },
        { document: { title: "Test 2" } },
        { document: { title: "Test 3" } },
      ],
      page: 1,
      search_time_ms: 123,
    };

    const encoder = new TextEncoder();
    const stream = new ReadableStream({
      start(controller) {
        chunks.forEach((chunk) => {
          controller.enqueue(encoder.encode(`data: ${chunk}\n\n`));
        });
        controller.enqueue(encoder.encode(JSON.stringify(metadata)));
        controller.close();
      },
    });

    mockFetch.mockResolvedValueOnce({
      ok: true,
      status: 200,
      headers: new Headers({ "content-type": "text/event-stream" }),
      body: stream,
    });

    const response = await client
      .collections<Essay>("test-collection")
      .documents()
      .search({
        q: "What is the maker schedule?",
        query_by: "embedding",
        conversation: true,
        conversation_stream: true,
        conversation_model_id: "test-model",
        include_fields: "title",
        streamConfig,
      });

    expect(onChunk.mock.calls.length).toBeGreaterThan(1);
    expect(onComplete).toHaveBeenCalledOnce();
    expect(onError).not.toHaveBeenCalled();
    expect(response).toBeDefined();
    expect(response.hits?.length).toBeGreaterThan(0);
  });

  it("should handle streaming responses for multisearch", async () => {
    const onChunk = vi.fn();
    const onComplete = vi.fn();
    const onError = vi.fn();

    const streamConfig: MultiSearchResultsStreamConfig<[Essay]> = {
      onChunk,
      onComplete,
      onError,
    };

    const chunks = [
      '{"conversation_id":"123","message":"First chunk"}',
      '{"conversation_id":"123","message":"Second chunk"}',
      '{"conversation_id":"123","message":"Final chunk"}',
    ];

    const metadata = {
      results: [
        {
          found: 3,
          hits: [
            { document: { title: "Test 1" } },
            { document: { title: "Test 2" } },
            { document: { title: "Test 3" } },
          ],
          page: 1,
          search_time_ms: 123,
        },
      ],
    };

    const encoder = new TextEncoder();
    const stream = new ReadableStream({
      start(controller) {
        chunks.forEach((chunk) => {
          controller.enqueue(encoder.encode(`data: ${chunk}\n\n`));
        });
        controller.enqueue(encoder.encode(JSON.stringify(metadata)));
        controller.close();
      },
    });

    mockFetch.mockResolvedValueOnce({
      ok: true,
      status: 200,
      headers: new Headers({ "content-type": "text/event-stream" }),
      body: stream,
    });

    const response = await client.multiSearch.perform<[Essay]>(
      {
        searches: [
          {
            collection: "test-collection",
            include_fields: "title",
          },
        ],
      },
      {
        conversation_stream: true,
        conversation: true,
        conversation_model_id: "test-model",
        query_by: "embedding",
        q: "What are the advantages and disadvantages of a startup being located in Silicon Valley?",
        streamConfig,
      },
    );

    expect(onChunk.mock.calls.length).toBeGreaterThan(1);
    expect(onComplete).toHaveBeenCalledOnce();
    expect(onError).not.toHaveBeenCalled();
    expect(response).toBeDefined();
    expect(response.results[0].hits?.length).toBeGreaterThan(0);
  });

  it("should invoke onError callback when an error occurs during stream processing", async () => {
    const onChunk = vi.fn();
    const onComplete = vi.fn();
    const onError = vi.fn();

    const streamConfig: StreamConfig<Essay> = {
      onChunk,
      onComplete,
      onError,
    };

    const encoder = new TextEncoder();
    const stream = new ReadableStream({
      start(controller) {
        controller.enqueue(
          encoder.encode(
            'data: {"conversation_id":"123","message":"Error chunk"}\n\n',
          ),
        );
        controller.error(new Error("Stream error during processing"));
      },
    });

    mockFetch.mockResolvedValueOnce({
      ok: true,
      status: 200,
      headers: new Headers({ "content-type": "text/event-stream" }),
      body: stream,
    });

    try {
      await client.collections<Essay>("test-collection").documents().search({
        q: "What is the maker schedule?",
        query_by: "embedding",
        conversation: true,
        conversation_stream: true,
        conversation_model_id: "test-model",
        include_fields: "title",
        streamConfig,
      });

      expect(true).toBe(false);
    } catch (error) {
      expect(onError).toHaveBeenCalledTimes(1);
      expect(onError.mock.calls[0][0]).toBeInstanceOf(Error);
      expect(onError.mock.calls[0][0].message).toBe(
        "Stream error during processing",
      );

      expect(onComplete).not.toHaveBeenCalled();
    }
  });
});

