import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { Client as TypesenseClient } from "../src/Typesense";

const { mockAxios, mockCancelFn } = vi.hoisted(() => {
  const mockCancelFn = vi.fn();
  const mockCancelSource = {
    token: "mock-cancel-token",
    cancel: mockCancelFn,
  };
  const mockAxios = vi.fn() as any;
  mockAxios.CancelToken = {
    source: vi.fn(() => mockCancelSource),
  };

  return { mockAxios, mockCancelFn };
});

vi.mock("axios", () => ({
  default: mockAxios,
  __esModule: true,
}));

describe("MultiSearch Abort Signal Tests", () => {
  let typesense: TypesenseClient;

  beforeEach(() => {
    vi.clearAllMocks();
    mockCancelFn.mockClear();

    typesense = new TypesenseClient({
      nodes: [
        {
          host: "node0",
          port: 8108,
          protocol: "http",
        },
      ],
      apiKey: "abcd",
      randomizeNodes: false,
    });

    mockAxios.mockResolvedValue({
      status: 200,
      data: { results: [{ hits: [] }] },
    });
  });

  afterEach(() => {
    vi.resetAllMocks();
  });

  it("should reject immediately if AbortSignal is already aborted", async () => {
    const abortController = new AbortController();
    abortController.abort(); // Abort immediately

    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    await expect(
      typesense.multiSearch.perform(
        searchRequests,
        {},
        {
          abortSignal: abortController.signal,
        },
      ),
    ).rejects.toThrow("Request aborted by caller.");

    // Verify axios was never called since request was aborted immediately
    expect(mockAxios).not.toHaveBeenCalled();
  });

  it("should create cancel token when AbortSignal is provided", async () => {
    const abortController = new AbortController();

    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    await typesense.multiSearch.perform(
      searchRequests,
      {},
      {
        abortSignal: abortController.signal,
      },
    );

    expect(mockAxios.CancelToken.source).toHaveBeenCalled();

    expect(mockAxios).toHaveBeenCalledWith(
      expect.objectContaining({
        cancelToken: "mock-cancel-token",
      }),
    );
  });

  it("should add abort event listener", async () => {
    const abortController = new AbortController();
    const addEventListenerSpy = vi.spyOn(
      abortController.signal,
      "addEventListener",
    );

    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    await typesense.multiSearch.perform(
      searchRequests,
      {},
      {
        abortSignal: abortController.signal,
      },
    );

    expect(addEventListenerSpy).toHaveBeenCalledWith(
      "abort",
      expect.any(Function),
    );
  });

  it("should remove abort event listener after completion", async () => {
    const abortController = new AbortController();
    const removeEventListenerSpy = vi.spyOn(
      abortController.signal,
      "removeEventListener",
    );

    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    await typesense.multiSearch.perform(
      searchRequests,
      {},
      {
        abortSignal: abortController.signal,
      },
    );

    expect(removeEventListenerSpy).toHaveBeenCalledWith(
      "abort",
      expect.any(Function),
    );
  });

  it("should work correctly without abort signal", async () => {
    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    const result = await typesense.multiSearch.perform(searchRequests, {});

    expect(mockAxios.CancelToken.source).not.toHaveBeenCalled();

    expect(mockAxios).toHaveBeenCalledWith(
      expect.not.objectContaining({
        cancelToken: expect.anything(),
      }),
    );

    expect(result).toEqual({ results: [{ hits: [] }] });
  });

  it("should handle streaming requests with abort signal", async () => {
    const abortController = new AbortController();

    const mockStream = {
      on: vi.fn((event, callback) => {
        if (event === "data") {
          setTimeout(() => callback('data: {"hits":[]}\n\n'), 1);
        }
        if (event === "end") {
          setTimeout(() => callback(), 2);
        }
        return mockStream;
      }),
      pipe: vi.fn(() => mockStream),
    };

    mockAxios.mockResolvedValueOnce({
      status: 200,
      data: mockStream,
    });

    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    const commonParams = {
      conversation: true,
      conversation_stream: true,
      streamConfig: {
        onChunk: vi.fn(),
        onComplete: vi.fn(),
        onError: vi.fn(),
      },
    };

    const result = await typesense.multiSearch.perform(
      searchRequests,
      commonParams,
      { abortSignal: abortController.signal },
    );

    expect(mockAxios.CancelToken.source).toHaveBeenCalled();

    expect(mockAxios).toHaveBeenCalledWith(
      expect.objectContaining({
        responseType: "stream",
        cancelToken: "mock-cancel-token",
      }),
    );

    expect(result).toBeDefined();
  });

  it("should handle error responses with abort signal", async () => {
    const abortController = new AbortController();

    mockAxios.mockResolvedValueOnce({
      status: 400,
      data: { message: "Bad request" },
    });

    const searchRequests = {
      searches: [{ q: "test query", collection: "documents" }],
    };

    await expect(
      typesense.multiSearch.perform(
        searchRequests,
        {},
        {
          abortSignal: abortController.signal,
        },
      ),
    ).rejects.toThrow();

    expect(mockAxios.CancelToken.source).toHaveBeenCalled();

    expect(mockAxios).toHaveBeenCalledWith(
      expect.objectContaining({
        cancelToken: "mock-cancel-token",
      }),
    );
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { SearchClient as TypesenseSearchClient } from "../../src/Typesense";
import MockAxiosAdapter from "axios-mock-adapter";
import axios from "axios";

describe("SearchClient", function () {
  let typesense: TypesenseSearchClient;
  let mockAxios: MockAxiosAdapter;

  beforeEach(function () {
    typesense = new TypesenseSearchClient({
      nodes: [
        {
          host: "node0",
          port: 8108,
          protocol: "http",
        },
      ],
      apiKey: "abcd",
      randomizeNodes: false,
      cacheSearchResultsForSeconds: 2 * 60,
    });

    mockAxios = new MockAxiosAdapter(axios);
  });

  afterEach(function () {
    mockAxios.reset();
  });

  it("should set the right default configuration values", function () {
    // @ts-expect-error - configuration is private
    expect(typesense.configuration.nodes).toEqual([
      {
        host: "node0",
        port: 8108,
        protocol: "http",
        path: "",
      },
    ]);
    // @ts-expect-error - configuration is private
    expect(typesense.configuration.connectionTimeoutSeconds).toEqual(5);
    // @ts-expect-error - configuration is private
    expect(typesense.configuration.apiKey).toEqual("abcd");
  });

  it("should only expose the search endpoints", function () {
    expect(typeof typesense.collections("xyz").documents().search).toBe(
      "function",
    );
    expect(typeof typesense.multiSearch.perform).toBe("function");
    // @ts-expect-error - keys is not defined
    expect(typesense.keys).toBeUndefined();
  });

  it("should send the api key via headers, when key is over 2000 characters, even if sendApiKeyAsQueryParam is true", async function () {
    const longApiKey = "a".repeat(2001);
    const testTypesense = new TypesenseSearchClient({
      nodes: [
        {
          host: "node0",
          port: 8108,
          protocol: "http",
        },
      ],
      apiKey: longApiKey,
      randomizeNodes: false,
      sendApiKeyAsQueryParam: true,
    });
    const searches = {
      searches: [{ q: "term1" }, { q: "term2" }],
    };
    const commonParams = {
      collection: "docs",
      query_by: "field",
    };

    mockAxios
      .onPost("http://node0:8108/multi_search", searches, {
        headers: {
          Accept: "application/json, text/plain, */*",
          "Content-Type": "text/plain",
          "X-TYPESENSE-API-KEY": longApiKey,
        },
      })
      .reply((config: any) => {
        expect(config.params["x-typesense-api-key"]).toBeUndefined();
        return [200, "{}", { "content-type": "application/json" }];
      });

    const returnData = await testTypesense.multiSearch.perform(
      searches,
      commonParams,
    );

    expect(returnData).toEqual({});
  });

  it("should programatically clear document cache", async function () {
    const documents = typesense.collections("companies").documents();
    const searchParameters = [
      {
        q: "Stark",
        query_by: "company_name",
      },
    ];
    const stubbedSearchResults = [
      {
        facet_counts: [],
        found: 0,
        search_time_ms: 0,
        page: 0,
        hits: [
          {
            _highlight: {
              company_name: "<mark>Stark</mark> Industries",
            },
            document: {
              id: "124",
              company_name: "Stark Industries",
              num_employees: 5215,
              country: "USA",
            },
          },
        ],
      },
    ];

    searchParameters.forEach((_, i: number) => {
      mockAxios
        .onGet("http://node0:8108/collections/companies/documents/search")
        .reply(200, JSON.stringify(stubbedSearchResults[i]), {
          "content-type": "application/json",
        });
    });

    await documents.search(searchParameters[0], {});

    typesense.clearCache();

    await documents.search(searchParameters[0], {});

    // if 2 requests are made, then we know that cache was cleared successfully
    expect(mockAxios.history["get"].length).toBe(2);
  });

  it("should programatically clear multi_search cache", async function () {
    const searchRequests = [
      {
        searches: [{ q: "term1" }, { q: "term2" }],
      },
    ];
    const commonParams = [
      {
        collection: "docs",
        query_by: "field",
      },
    ];
    const stubbedSearchResults = [{ results1: [] }, { results2: [] }];

    searchRequests.forEach((_, i: number) => {
      mockAxios
        .onPost("http://node0:8108/multi_search")
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        .reply((config: any) => {
          return [
            200,
            JSON.stringify(stubbedSearchResults[i]),
            { "content-type": "application/json" },
          ];
        });
    });

    await typesense.multiSearch.perform(searchRequests[0], commonParams[0]);

    // programmatically clear cache
    typesense.clearCache();

    await typesense.multiSearch.perform(searchRequests[0], commonParams[0]);

    // if 2 requests are made, then we know that cache was cleared successfully
    expect(mockAxios.history["post"].length).toBe(2);
  });

  it("should cache multi_search requests using client configuration by default", async function () {
    const searchRequest = {
      searches: [{ q: "term1" }, { q: "term2" }],
    };
    const commonParams = {
      collection: "docs",
      query_by: "field",
    };

    mockAxios
      .onPost("http://node0:8108/multi_search")
      .reply(200, JSON.stringify({ results: [] }), {
        "content-type": "application/json",
      });

    await typesense.multiSearch.perform(searchRequest, commonParams);
    await typesense.multiSearch.perform(searchRequest, commonParams);

    expect(mockAxios.history["post"].length).toBe(1);
  });

  it("should not cache failed multi_search requests", async function () {
    typesense = new TypesenseSearchClient({
      nodes: [
        {
          host: "node0",
          port: 8108,
          protocol: "http",
        },
      ],
      apiKey: "abcd",
      randomizeNodes: false,
      numRetries: 0,
      cacheSearchResultsForSeconds: 2 * 60,
    });
    const searchRequest = {
      searches: [{ q: "term1" }],
    };
    const commonParams = {
      collection: "docs",
      query_by: "field",
    };

    mockAxios
      .onPost("http://node0:8108/multi_search")
      .networkErrorOnce()
      .onPost("http://node0:8108/multi_search")
      .reply(200, JSON.stringify({ results: [] }), {
        "content-type": "application/json",
      });

    await expect(
      typesense.multiSearch.perform(searchRequest, commonParams),
    ).rejects.toThrow();

    const response = await typesense.multiSearch.perform(
      searchRequest,
      commonParams,
    );

    expect(response).toEqual({ results: [] });
    expect(mockAxios.history["post"].length).toBe(2);
  });
});

