      // Ignore if collection doesn't exist
    }

    await typesense.collections().create({
      name: testCollectionName,
      fields: [
        {
          name: "title",
          type: "string",
          facet: true,
          sort: true,
        },
        {
          name: "content",
          type: "string",
          facet: true,
          sort: true,
        },
        {
          name: "tags",
          type: "string[]",
          facet: true,
